+	stateDir := filepath.Join(dir, ".git", session.SessionStateDirName)
+	store := session.NewStateStoreWithDir(stateDir)
+	repo, err := gitrepo.OpenPath(dir)
+	if err != nil {
+		t.Fatalf("open repo after PostCommit: %v", err)
+	}
+	defer repo.Close()
+
+	for _, seeded := range fixture.endedWithShadow {
+		state, loadErr := store.Load(ctx, seeded.sessionID)
+		if loadErr != nil {
+			t.Fatalf("load condensed state %s: %v", seeded.sessionID, loadErr)
+		}
+		if state == nil {
+			t.Fatalf("condensed state %s was removed", seeded.sessionID)
+		}
+		if state.LastCheckpointID != checkpointID {
+			t.Fatalf("state %s checkpoint = %s, want %s", seeded.sessionID, state.LastCheckpointID, checkpointID)
+		}
+		if !state.FullyCondensed {
+			t.Fatalf("state %s was not marked fully condensed", seeded.sessionID)
+		}
+		if _, refErr := repo.Reference(seeded.shadowRef, true); refErr == nil {
+			t.Fatalf("condensed shadow ref %s was not cleaned up", seeded.shadowRef)
+		}
+	}
+}
+
+type hookPerfTimings struct {
+	findSessions    time.Duration
+	processSessions time.Duration
+	condensations   int
+	extract         time.Duration
+	attribution     time.Duration
+	redaction       time.Duration
+	write           time.Duration
+	condenseTotal   time.Duration
+}
+
+type hookPerfLogEntry struct {
+	Message       string `json:"msg"`
+	Operation     string `json:"op"`
+	DurationMS    int64  `json:"duration_ms"`
+	ExtractMS     int64  `json:"extract_session_data_ms"`
+	AttributionMS int64  `json:"calculate_session_attribution_ms"`
+	RedactionMS   int64  `json:"redact_transcript_ms"`
+	WriteMS       int64  `json:"write_committed_v1_ms"`
+	TotalMS       int64  `json:"total_ms"`
+}
+
+func readHookPerfTimings(t *testing.T, dir string) hookPerfTimings {
+	t.Helper()
+	logPath := filepath.Join(dir, logging.LogsDir, "entire.log")
+	file, err := os.Open(logPath)
+	if err != nil {
+		t.Fatalf("open performance log: %v", err)
+	}
+	defer file.Close()
+
+	var timings hookPerfTimings
+	scanner := bufio.NewScanner(file)
+	scanner.Buffer(make([]byte, 64*1024), 4*1024*1024)
+	for scanner.Scan() {
+		var entry hookPerfLogEntry
+		if unmarshalErr := json.Unmarshal(scanner.Bytes(), &entry); unmarshalErr != nil {
+			t.Fatalf("parse performance log entry: %v\n%s", unmarshalErr, scanner.Text())
+		}
+		if entry.Message == "perf" {
+			switch entry.Operation {
+			case "find_sessions_for_worktree":
+				timings.findSessions = time.Duration(entry.DurationMS) * time.Millisecond
+			case "process_sessions":
+				timings.processSessions = time.Duration(entry.DurationMS) * time.Millisecond
+			}
+		}
+		if entry.Message != "condense timings" {
+			continue
+		}
+		timings.condensations++
+		timings.extract += time.Duration(entry.ExtractMS) * time.Millisecond
+		timings.attribution += time.Duration(entry.AttributionMS) * time.Millisecond
+		timings.redaction += time.Duration(entry.RedactionMS) * time.Millisecond
+		timings.write += time.Duration(entry.WriteMS) * time.Millisecond
+		timings.condenseTotal += time.Duration(entry.TotalMS) * time.Millisecond
+	}
+	if scanErr := scanner.Err(); scanErr != nil {
+		t.Fatalf("scan performance log: %v", scanErr)
+	}
+	if timings.processSessions == 0 {
+		t.Fatal("performance log has no non-zero process_sessions measurement")
+	}
+	if timings.condensations == 0 {
+		t.Fatal("performance log has no condensation measurements")
+	}
+	return timings
 }

