101		newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, checkpointSubtree)
102		if err != nil {
103			return err
104		}
105		newTreeHash, err = s.maybeMergeVercelConfig(ctx, newTreeHash)
106		if err != nil {
107			return err
108		}
