126			return nil, nil //nolint:nilnil // absent checkpoint (no tree yet), not an error
127		}
128		rootTree, err := s.repo.TreeObject(rootTreeHash)
129		if err != nil {
130			if errors.Is(err, plumbing.ErrObjectNotFound) {
131				return nil, nil //nolint:nilnil // tree doesn't exist yet, not an error
132			}
133			return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
134		}
135		if path == "" {
136			return rootTree, nil
137		}
138		subtree, err := rootTree.Tree(path)
