145	// checkpointSubtreePath joins a checkpoint-relative git tree path from a base and
146	// trailing segments using path.Join. Git tree paths are always "/"-separated, so
147	// this uses the stdlib path package (never path/filepath, which would emit "\" on
148	// Windows and corrupt tree keys). path.Join cleans separators, so base may be ""
149	// (per-checkpoint-ref root), a clean dir ("a3/b2.../0"), or a trailing-slash dir
150	// ("a3/b2.../"): checkpointSubtreePath("", "0", "metadata.json") == "0/metadata.json"
151	// and checkpointSubtreePath("a3/b2.../", "0", "metadata.json") == "a3/b2.../0/metadata.json".
152	// Callers therefore need not maintain the trailing-slash invariant by hand.
153	func checkpointSubtreePath(base string, segs ...string) string {
154		if len(segs) == 0 {
155			// path.Join with no segments would clean a "" base to "." — an invalid
156			// git tree key. At the ref root the correct key is ""; for a non-empty
157			// base, clean it to keep the trailing-slash-stripping behavior.
158			if base == "" {
159				return ""
160			}
161			return path.Clean(base)
162		}
163		return path.Join(append([]string{base}, segs...)...)
164	}
165	
166	// flattenExisting flattens a checkpoint's current subtree into a path->entry map
167	// keyed under basePath, so the per-checkpoint write helpers (which build paths as
168	// basePath+"<n>/<file>") see the existing files. basePath is "" for the
169	// per-checkpoint-ref layout or "<shard>/<id>/" for the v1 branch layout. A nil
170	// subtree (new checkpoint) yields an empty map.
171	func (s *treeWriter) flattenExisting(existing *object.Tree, basePath string) (map[string]object.TreeEntry, error) {
172		entries := make(map[string]object.TreeEntry)
173		if existing == nil {
174			return entries, nil
175		}
176		if err := FlattenTree(s.repo, existing, strings.TrimSuffix(basePath, "/"), entries); err != nil {
177			return nil, err
178		}
179		return entries, nil
180	}
181	
182	// buildCheckpointSubtree builds the checkpoint subtree object from entries keyed
183	// under basePath, stripping the prefix so the subtree is rooted at the checkpoint
184	// directory. With basePath "" the entries are already root-relative.
185	func (s *treeWriter) buildCheckpointSubtree(ctx context.Context, entries map[string]object.TreeEntry, basePath string) (plumbing.Hash, error) {
186		relEntries := entries
187		if basePath != "" {
188			relEntries = make(map[string]object.TreeEntry, len(entries))
189			for path, entry := range entries {
190				relPath := strings.TrimPrefix(path, basePath)
191				if relPath == path {
192					continue // Entry doesn't have the expected prefix
193				}
194				relEntries[relPath] = entry
195			}
196		}
197		subtree, err := BuildTreeFromEntries(ctx, s.repo, relEntries)
198		if err != nil {
199			return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
200		}
201		return subtree, nil
202	}
203	
204	// spliceCheckpointSubtree installs a prebuilt checkpoint subtree at the shard
205	// location in the v1 root tree using O(depth) tree surgery, returning the new
206	// root tree hash. The v1 branch always shards on the first two ID characters.
207	func (s *GitStore) spliceCheckpointSubtree(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, checkpointSubtree plumbing.Hash) (plumbing.Hash, error) {
208		shardPrefix := string(checkpointID[:2])
209		shardSuffix := string(checkpointID[2:])
210		return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
211			{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointSubtree},
212		}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
213	}
