215	// applySessionWrite applies a Session write to a checkpoint's current subtree
216	// and returns the new checkpoint subtree hash. It is backing-independent: the
217	// v1-branch store passes the sharded basePath and the per-checkpoint-ref
218	// store passes "".
219	func (s *treeWriter) applySessionWrite(ctx context.Context, opts WriteOptions, existing *object.Tree, basePath string) (plumbing.Hash, error) {
220		entries, err := s.flattenExisting(existing, basePath)
221		if err != nil {
222			return plumbing.ZeroHash, err
223		}
224	
225		if err := s.writeTaskRecordEntries(opts, basePath, entries); err != nil {
226			return plumbing.ZeroHash, err
227		}
228	
229		if err := s.writeStandardCheckpointEntries(ctx, opts, basePath, entries); err != nil {
230			return plumbing.ZeroHash, err
231		}
232	
233		return s.buildCheckpointSubtree(ctx, entries, basePath)
234	}
235	
236	// applyAttributionBackfill rewrites the checkpoint root summary's combined
237	// attribution on the checkpoint's current subtree, returning the new subtree
238	// hash. Returns ErrCheckpointNotFound when the checkpoint has no root summary.
239	func (s *treeWriter) applyAttributionBackfill(ctx context.Context, existing *object.Tree, basePath string, combinedAttribution *Attribution) (plumbing.Hash, error) {
240		entries, err := s.flattenExisting(existing, basePath)
241		if err != nil {
242			return plumbing.ZeroHash, err
243		}
244	
245		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
246		entry, exists := entries[rootMetadataPath]
