275	// current subtree, returning the new subtree hash and that session's ID (for the
276	// commit message). Returns ErrCheckpointNotFound when the checkpoint has no root
277	// summary.
278	func (s *treeWriter) applySummaryBackfill(ctx context.Context, existing *object.Tree, basePath string, summary *Summary) (plumbing.Hash, string, error) {
