	if len(mirrors) == 0 {
		return primary
	}
	base := &fanoutStore{primary: primary, mirrors: mirrors}
	if author, ok := primary.(AuthorReader); ok {
		return &fanoutStoreWithAuthor{fanoutStore: base, author: author}
	}
	return base
}

