555	func (s *treeWriter) writeStandardCheckpointEntries(ctx context.Context, opts WriteOptions, basePath string, entries map[string]object.TreeEntry) error {
556		// Read existing summary to get current session count
557		var existingSummary *CheckpointSummary
558		metadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
559		if entry, exists := entries[metadataPath]; exists {
560			existing, err := s.readSummaryFromBlob(entry.Hash)
561			if err == nil {
562				existingSummary = existing
563			} else {
564				logging.Debug(ctx, "writeStandardCheckpointEntries: readSummaryFromBlob failed",
565					slog.String("metadata_path", metadataPath),
566					slog.String("error", err.Error()))
567			}
568		}
569	
570		// Determine session index: reuse existing slot if session ID matches, otherwise append
571		sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
572	
573		// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
574		// findSessionIndex only returns 0 when existingSummary is nil (fresh write)
575		// or when the summary claims slot 0 belongs to us — either way, the tree
576		// actually holding session-0 metadata for someone else is a corruption /
577		// stale-summary shape. Writing through it would overwrite data we don't
578		// know about. Bail instead of silently clobbering.
579		//
580		// We read and capture BEFORE writeSessionToSubdirectory clears the subtree,
581		// otherwise we'd only ever see our own write.
582		if sessionIndex == 0 {
583			if entry, exists := entries[checkpointSubtreePath(basePath, "0", paths.MetadataFileName)]; exists {
584				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
585					logging.Error(ctx, "refusing checkpoint write: session 0 holds a different sessionID",
586						slog.String("checkpoint_id", opts.CheckpointID.String()),
587						slog.String("existing_session_id", existingMeta.SessionID),
588						slog.String("write_session_id", opts.SessionID),
589						slog.Bool("existing_summary_nil", existingSummary == nil))
590					return fmt.Errorf(
591						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree entire/checkpoints/v1 %s/`",
592						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, opts.CheckpointID.Path(),
593					)
594				}
595			}
596		}
597	
598		// Write session files to numbered subdirectory
599		sessionDir := checkpointSubtreePath(basePath, strconv.Itoa(sessionIndex))
600		sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionDir, entries)
601		if err != nil {
602			return err
603		}
604	
605		// Copy additional metadata files from directory if specified (to session subdirectory)
606		if opts.MetadataDir != "" {
607			if err := s.copyMetadataDir(ctx, opts.MetadataDir, sessionDir, entries); err != nil {
608				return fmt.Errorf("failed to copy metadata directory: %w", err)
609			}
610		}
611	
612		// Build the sessions array
613		var sessions []SessionFilePaths
614		if existingSummary != nil {
615			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
616			copy(sessions, existingSummary.Sessions)
617		} else {
618			sessions = make([]SessionFilePaths, 1)
619		}
620		sessions[sessionIndex] = sessionFilePaths
621	
622		// Tripwire: an unreproduced production report had session 0 silently
623		// replaced with a different sessionID's data. The symptom was
624		// findSessionIndex returning 0 when it should have returned N
625		// (append). That happens if existingSummary is nil — yet the
